<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import api from '@/api'
import { dateTime, statusMap } from '@/utils/format'

const loading=ref(false);const result=reactive({items:[],total:0});const params=reactive({keyword:'',status_filter:'',role:'',page:1,page_size:20})
const load=async()=>{loading.value=true;try{Object.assign(result,await api.get('/admin/users',{params}))}finally{loading.value=false}}
const changeStatus=async(row,status)=>{const r=await ElMessageBox.prompt(`将用户状态修改为“${statusMap[status][0]}”`, '用户状态管理',{inputPlaceholder:'请填写操作原因',confirmButtonText:'确认操作',cancelButtonText:'取消'}).catch(()=>null);if(!r)return;await api.patch(`/admin/users/${row.id}/status`,{status,reason:r.value});ElMessage.success('用户状态已更新');load()}
onMounted(load)
</script>
<template><div><div class="admin-filters"><el-input v-model="params.keyword" clearable placeholder="搜索用户名、昵称、邮箱或学号" @keyup.enter="load"><template #prefix><el-icon><Search /></el-icon></template></el-input><el-select v-model="params.status_filter" clearable placeholder="账号状态" style="width:140px"><el-option label="正常" value="active"/><el-option label="暂停" value="suspended"/><el-option label="封禁" value="banned"/></el-select><el-select v-model="params.role" clearable placeholder="用户角色" style="width:140px"><el-option label="普通用户" value="user"/><el-option label="管理员" value="admin"/><el-option label="审核员" value="moderator"/></el-select><el-button type="success" @click="params.page=1;load()">查询</el-button><el-button @click="Object.assign(params,{keyword:'',status_filter:'',role:'',page:1});load()">重置</el-button><span class="filter-count">共 {{result.total}} 位用户</span></div><section class="admin-card"><el-table v-loading="loading" :data="result.items"><el-table-column label="用户" min-width="200"><template #default="{row}"><div class="user-cell"><span class="avatar small">{{row.nickname.slice(0,1)}}</span><div><strong>{{row.nickname}}</strong><small>@{{row.username}}</small></div></div></template></el-table-column><el-table-column label="学校 / 学号" min-width="180"><template #default="{row}"><span>{{row.campus}}</span><small class="block">{{row.student_no||'未填写'}}</small></template></el-table-column><el-table-column label="认证"><template #default="{row}"><el-tag :type="row.verified?'success':'info'">{{row.verified?'已认证':'未认证'}}</el-tag></template></el-table-column><el-table-column label="角色"><template #default="{row}">{{{user:'普通用户',admin:'管理员',moderator:'审核员'}[row.role]}}</template></el-table-column><el-table-column label="信用分"><template #default="{row}"><strong :class="row.credit_score<80?'danger-text':'credit-text'">{{row.credit_score}}</strong></template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="statusMap[row.status]?.[1]">{{statusMap[row.status]?.[0]}}</el-tag></template></el-table-column><el-table-column label="注册时间" width="160"><template #default="{row}">{{dateTime(row.created_at)}}</template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-dropdown v-if="row.role!=='admin'"><el-button size="small">管理 <el-icon><ArrowDown/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="changeStatus(row,'active')">恢复正常</el-dropdown-item><el-dropdown-item @click="changeStatus(row,'suspended')">暂停账号</el-dropdown-item><el-dropdown-item divided @click="changeStatus(row,'banned')">封禁账号</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-tag v-else type="info">系统账号</el-tag></template></el-table-column></el-table><div class="pagination-row"><el-pagination v-model:current-page="params.page" background layout="total, prev, pager, next" :total="result.total" :page-size="params.page_size" @current-change="load"/></div></section></div></template>
<style scoped>.filter-count{margin-left:auto;color:#7f8982;font-size:12px}.user-cell{display:flex;align-items:center;gap:9px}.user-cell strong,.user-cell small{display:block}.user-cell small,.block{margin-top:3px;color:#959d97;font-size:10px}.credit-text{color:#278040}.danger-text{color:#d54f48}</style>

